PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE `survey_answers` (
	`id` text PRIMARY KEY NOT NULL,
	`response_id` text NOT NULL,
	`question_code` text NOT NULL,
	`answer_value` text NOT NULL,
	`numeric_score` real,
	FOREIGN KEY (`response_id`) REFERENCES `survey_responses`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `survey_followups` (
	`id` text PRIMARY KEY NOT NULL,
	`response_id` text NOT NULL,
	`reason` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`assigned_to` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	FOREIGN KEY (`response_id`) REFERENCES `survey_responses`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `survey_responses` (
	`id` text PRIMARY KEY NOT NULL,
	`submission_key` text NOT NULL,
	`survey_type` text NOT NULL,
	`respondent_hash` text NOT NULL,
	`submission_date` text NOT NULL,
	`ticket_reference` text,
	`engineer_name` text,
	`resolved_status` text,
	`overall_score` real NOT NULL,
	`nps_score` integer,
	`comment` text,
	`needs_followup` integer DEFAULT false NOT NULL,
	`submitted_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `ticket_events` (
	`id` text PRIMARY KEY NOT NULL,
	`ticket_id` text NOT NULL,
	`event_type` text NOT NULL,
	`from_status` text,
	`to_status` text,
	`actor_name` text NOT NULL,
	`note` text,
	`created_at` text NOT NULL,
	FOREIGN KEY (`ticket_id`) REFERENCES `tickets`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `tickets` (
	`id` text PRIMARY KEY NOT NULL,
	`ticket_number` text NOT NULL,
	`requester_hash` text NOT NULL,
	`requester_name` text NOT NULL,
	`requester_email` text NOT NULL,
	`department` text NOT NULL,
	`title` text NOT NULL,
	`description` text NOT NULL,
	`category` text NOT NULL,
	`priority` text NOT NULL,
	`source` text NOT NULL,
	`location` text,
	`asset_tag` text,
	`assigned_team` text NOT NULL,
	`status` text DEFAULT '待處理' NOT NULL,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL
, assigned_team_id TEXT, assigned_user_id TEXT, ai_suggested_team_id TEXT, assignment_source TEXT, assigned_at TEXT);
CREATE TABLE `app_users` (
	`id` text PRIMARY KEY NOT NULL,
	`email` text NOT NULL,
	`display_name` text NOT NULL,
	`department` text,
	`role_id` text NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`last_login_at` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL, `username` text, `password_hash` text, `password_salt` text, `password_changed_at` text, team_id TEXT, is_assignable INTEGER NOT NULL DEFAULT 0, must_change_password INTEGER NOT NULL DEFAULT 0,
	FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `assets` (
	`id` text PRIMARY KEY NOT NULL,
	`asset_tag` text NOT NULL,
	`name` text NOT NULL,
	`asset_type` text NOT NULL,
	`owner_name` text,
	`department` text,
	`location` text,
	`status` text DEFAULT '使用中' NOT NULL,
	`warranty_end` text,
	`notes` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `audit_logs` (
	`id` text PRIMARY KEY NOT NULL,
	`actor_email` text NOT NULL,
	`action` text NOT NULL,
	`entity_type` text NOT NULL,
	`entity_id` text,
	`details` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `managed_services` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`service_type` text NOT NULL,
	`owner_team` text NOT NULL,
	`status` text DEFAULT '正常' NOT NULL,
	`availability` real DEFAULT 100 NOT NULL,
	`endpoint` text,
	`description` text,
	`last_checked_at` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `roles` (
	`id` text PRIMARY KEY NOT NULL,
	`code` text NOT NULL,
	`name` text NOT NULL,
	`permissions` text NOT NULL,
	`is_system` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `auth_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`token_hash` text NOT NULL,
	`expires_at` text NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`last_seen_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`revoked_at` text,
	FOREIGN KEY (`user_id`) REFERENCES `app_users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE support_teams (
  id TEXT PRIMARY KEY NOT NULL,
  team_code TEXT NOT NULL UNIQUE,
  team_name TEXT NOT NULL,
  description TEXT,
  display_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_by TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by TEXT
);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE login_attempts (
  id text PRIMARY KEY NOT NULL,
  login_key text NOT NULL,
  ip_hash text NOT NULL,
  succeeded integer DEFAULT 0 NOT NULL,
  created_at text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX `survey_answers_response_question_uq` ON `survey_answers` (`response_id`,`question_code`);
CREATE INDEX `survey_answers_response_idx` ON `survey_answers` (`response_id`);
CREATE UNIQUE INDEX `survey_followups_response_uq` ON `survey_followups` (`response_id`);
CREATE INDEX `survey_followups_status_idx` ON `survey_followups` (`status`);
CREATE UNIQUE INDEX `survey_responses_submission_key_uq` ON `survey_responses` (`submission_key`);
CREATE UNIQUE INDEX `survey_responses_ticket_reference_uq` ON `survey_responses` (`ticket_reference`);
CREATE INDEX `survey_responses_type_date_idx` ON `survey_responses` (`survey_type`,`submitted_at`);
CREATE INDEX `ticket_events_ticket_created_idx` ON `ticket_events` (`ticket_id`,`created_at`);
CREATE UNIQUE INDEX `tickets_ticket_number_uq` ON `tickets` (`ticket_number`);
CREATE INDEX `tickets_requester_created_idx` ON `tickets` (`requester_hash`,`created_at`);
CREATE INDEX `tickets_status_priority_idx` ON `tickets` (`status`,`priority`);
CREATE UNIQUE INDEX `app_users_email_uq` ON `app_users` (`email`);
CREATE INDEX `app_users_role_status_idx` ON `app_users` (`role_id`,`status`);
CREATE UNIQUE INDEX `assets_asset_tag_uq` ON `assets` (`asset_tag`);
CREATE INDEX `assets_type_status_idx` ON `assets` (`asset_type`,`status`);
CREATE INDEX `audit_logs_actor_created_idx` ON `audit_logs` (`actor_email`,`created_at`);
CREATE INDEX `audit_logs_entity_created_idx` ON `audit_logs` (`entity_type`,`created_at`);
CREATE UNIQUE INDEX `managed_services_name_uq` ON `managed_services` (`name`);
CREATE INDEX `managed_services_status_idx` ON `managed_services` (`status`);
CREATE UNIQUE INDEX `roles_code_uq` ON `roles` (`code`);
CREATE UNIQUE INDEX `auth_sessions_token_hash_uq` ON `auth_sessions` (`token_hash`);
CREATE INDEX `auth_sessions_user_expires_idx` ON `auth_sessions` (`user_id`,`expires_at`);
CREATE UNIQUE INDEX `app_users_username_uq` ON `app_users` (`username`);
CREATE INDEX support_teams_active_order_idx ON support_teams(is_active, display_order, team_name);
CREATE INDEX app_users_team_assignable_idx ON app_users(team_id, is_assignable, status);
CREATE INDEX tickets_assigned_team_idx ON tickets(assigned_team_id);
CREATE INDEX tickets_assigned_user_idx ON tickets(assigned_user_id);
CREATE INDEX idx_support_teams_active_order
ON support_teams (is_active, display_order);
CREATE INDEX idx_app_users_team_assignable
ON app_users (team_id, is_assignable, status);
CREATE INDEX idx_tickets_assigned_team_id
ON tickets (assigned_team_id);
CREATE INDEX idx_tickets_assigned_user_id
ON tickets (assigned_user_id);
CREATE INDEX idx_tickets_assignment_status
ON tickets (assigned_team_id, assigned_user_id, status);
CREATE UNIQUE INDEX survey_responses_system_user_uq
ON survey_responses (survey_type, respondent_hash)
WHERE survey_type = 'system_usage';
CREATE INDEX login_attempts_lookup_idx
  ON login_attempts(login_key, ip_hash, created_at);
CREATE INDEX auth_sessions_active_idx
  ON auth_sessions(token_hash, expires_at, revoked_at);
CREATE UNIQUE INDEX `support_teams_code_uq` ON `support_teams` (`team_code`);
CREATE INDEX app_users_status_username_idx
  ON app_users(status, username);
